package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Entities_escape_TriageGen0Test {

    private Entities entities;

    @Before
    public void setUp() {
        entities = new Entities();
    }

    @Test
    public void testEscape_NullInput() {
        // Note: The current implementation would throw a NullPointerException on str.length()
        // This test documents the current behavior for a null input.
        try {
            entities.escape(null);
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            // Expected
        }
    }

    @Test
    public void testEscape_EmptyString() {
        assertEquals("", entities.escape(""));
    }

    @Test
    public void testEscape_NormalAscii() {
        // Tests the branch where entityName is null and ch <= 0x7F
        assertEquals("abc 123", entities.escape("abc 123"));
    }

    @Test
    public void testEscape_WithEntity() {
        // Tests the branch where entityName is NOT null
        // Assuming standard HTML entities like '<' or '&' are handled by entityName()
        // Since we don't see entityName implementation, we rely on known standard behavior 
        // or the fact that it returns a String for certain chars.
        // Let's assume '&' is an entity.
        String input = "&";
        String result = entities.escape(input);
        // If '&' is an entity, it should result in "&amp;" or similar.
        // If it's not, it would just be "&". 
        // To ensure branch coverage, we test a char that definitely has an entity name.
        // Using '<' (if it's in the default map)
        String result2 = entities.escape("<");
        assertNotEquals("<", result2);
    }

    @Test
    public void testEscape_WithHighAscii() {
        // Tests the branch where entityName is null and ch > 0x7F
        // 0x80 is 128
        String input = "\u0080";
        String expected = "&#128;";
        assertEquals(expected, entities.escape(input));
    }

    @Test
    public void testEscape_MixedContent() {
        // Combines all branches:
        // 1. entityName != null (e.g., '&')
        // 2. entityName == null && ch <= 0x7F (e.g., 'A')
        // 3. entityName == null && ch > 0x7F (e.g., '\u0080')

        // We use a custom entity via addEntity to guarantee the branch coverage
        entities.addEntity("test", 123);

        // We need a character that results in "test" via entityName(ch)
        // Since entityName(ch) is called, we need to know which char maps to "test"
        // Because we can't know the internal mapping without implementation, 
        // we will trigger the logic by assuming standard entities or using the provided addEntity

        // Let's test with a character we know is likely an entity in Commons Lang
        // and a high-bit character.
        String input = "A\u0080&"; 
        String result = entities.escape(input);

        // 'A' -> 'A'
        // '\u0080' -> '&#128;'
        // '&' -> '&amp;' (assuming standard)
        assertTrue(result.contains("A"));
        assertTrue(result.contains("&#128;"));
        assertTrue(result.contains("&")); 
    }

    @Test
    public void testEscape_MaxBranchCoverage() {
        // Forceful coverage of the logic:
        // Branch 1: entityName != null
        // Branch 2: entityName == null && ch > 0x7F
        // Branch 3: entityName == null && ch <= 0x7F

        // We use addEntity to ensure we can trigger entityName != null
        // However, addEntity(name, value) usually maps name -> value.
        // entityName(char) maps char -> name.
        // So we need to find which char maps to a name.

        // Let's use a character that is known to be handled by default Entities
        // In Apache Commons Lang, '&' is typically an entity.
        String input = "&" + "A" + "\u00FF";
        String result = entities.escape(input);

        // Expected:
        // '&' -> '&' + entityName('&') + ';'
        // 'A' -> 'A'
        // '\u00FF' -> '&#255;'

        assertTrue(result.startsWith("&"));
        assertTrue(result.contains("A"));
        assertTrue(result.contains("&#255;"));
    }
}
